335→#[cfg(test)]
336→mod tests {
337→    use super::*;
338→    use tempfile::TempDir;
339→
340→    #[test]
341→    fn state_store_new() {
342→        let temp = TempDir::new().unwrap();
343→        let project = ProjectId::from_path(temp.path()).unwrap();
344→        let state = StateStore::new(&project);
345→
346→        assert_eq!(state.version, StateStore::CURRENT_VERSION);
347→        assert!(state.last_run.is_none());
348→        assert!(state.steps.is_empty());
349→    }
350→
351→    #[test]
352→    fn state_store_save_and_load() {
353→        let temp = TempDir::new().unwrap();
354→        let project = ProjectId::from_path(temp.path()).unwrap();
355→
356→        let mut state = StateStore::new(&project);
357→        state.update_step(
358→            "test_step",
359→            StepState {
360→                status: StepStatus::Success,
361→                last_run: Some(Utc::now()),
362→                duration_ms: Some(1000),
363→                watches_hash: None,
364→            },
365→        );
366→
367→        state.save(&project).unwrap();
368→
369→        let loaded = StateStore::load(&project).unwrap();
370→        assert!(loaded.get_step("test_step").is_some());
371→        assert_eq!(
372→            loaded.get_step("test_step").unwrap().status,
373→            StepStatus::Success
374→        );
375→    }
376→
377→    #[test]
378→    fn state_store_load_nonexistent_returns_new() {
379→        let temp = TempDir::new().unwrap();
380→        let project = ProjectId::from_path(temp.path()).unwrap();
381→
382→        let state = StateStore::load(&project).unwrap();
383→        assert!(state.steps.is_empty());
384→    }
385→
386→    #[test]
387→    fn step_status_serializes() {
388→        let state = StepState {
389→            status: StepStatus::Success,
390→            ..Default::default()
391→        };
392→
393→        let yaml = serde_yaml::to_string(&state).unwrap();
394→        assert!(yaml.contains("Success"));
395→    }
396→
397→    #[test]
398→    fn save_uses_atomic_write() {
399→        let temp = TempDir::new().unwrap();
400→        let project = ProjectId::from_path(temp.path()).unwrap();
401→
402→        let mut state = StateStore::new(&project);
403→        state.update_step(
404→            "test_step",
405→            StepState {
406→                status: StepStatus::Success,
407→                ..Default::default()
408→            },
409→        );
410→
411→        // Save state
412→        state.save(&project).unwrap();
413→
414→        // Verify no temp file remains (it should have been renamed)
415→        let temp_path = StateStore::state_file(&project).with_extension("yml.tmp");
416→        assert!(
417→            !temp_path.exists(),
418→            "Temp file should not exist after successful save"
419→        );
420→
421→        // Verify actual state file exists and is valid
422→        let loaded = StateStore::load(&project).unwrap();
423→        assert_eq!(
424→            loaded.get_step("test_step").unwrap().status,
425→            StepStatus::Success
426→        );
427→    }
428→}
