430→#[cfg(test)]
431→mod step_state_tests {
432→    use super::*;
433→    use tempfile::TempDir;
434→
435→    #[test]
436→    fn record_step_result() {
437→        let temp = TempDir::new().unwrap();
438→        let project = ProjectId::from_path(temp.path()).unwrap();
439→        let mut state = StateStore::new(&project);
440→
441→        state.record_step_result(
442→            "test",
443→            StepStatus::Success,
444→            std::time::Duration::from_secs(5),
445→            Some("hash123".to_string()),
446→        );
447→
448→        let step = state.get_step("test").unwrap();
449→        assert_eq!(step.status, StepStatus::Success);
450→        assert_eq!(step.duration_ms, Some(5000));
451→        assert_eq!(step.watches_hash, Some("hash123".to_string()));
452→    }
453→
454→    #[test]
455→    fn is_step_complete() {
456→        let temp = TempDir::new().unwrap();
457→        let project = ProjectId::from_path(temp.path()).unwrap();
458→        let mut state = StateStore::new(&project);
459→
460→        assert!(!state.is_step_complete("test"));
461→
462→        state.record_step_result(
463→            "test",
464→            StepStatus::Success,
465→            std::time::Duration::from_secs(1),
466→            None,
467→        );
468→
469→        assert!(state.is_step_complete("test"));
470→    }
471→
472→    #[test]
473→    fn is_step_complete_false_for_failed() {
474→        let temp = TempDir::new().unwrap();
475→        let project = ProjectId::from_path(temp.path()).unwrap();
476→        let mut state = StateStore::new(&project);
477→
478→        state.record_step_result(
479→            "test",
480→            StepStatus::Failed,
481→            std::time::Duration::from_secs(1),
482→            None,
483→        );
484→
485→        assert!(!state.is_step_complete("test"));
486→    }
487→
488→    #[test]
489→    fn clear_step() {
490→        let temp = TempDir::new().unwrap();
491→        let project = ProjectId::from_path(temp.path()).unwrap();
492→        let mut state = StateStore::new(&project);
493→
494→        state.record_step_result("test", StepStatus::Success, std::time::Duration::ZERO, None);
495→        assert!(state.get_step("test").is_some());
496→
497→        state.clear_step("test");
498→        assert!(state.get_step("test").is_none());
499→    }
500→
501→    #[test]
502→    fn clear_all_steps() {
503→        let temp = TempDir::new().unwrap();
504→        let project = ProjectId::from_path(temp.path()).unwrap();
505→        let mut state = StateStore::new(&project);
506→
507→        state.record_step_result("a", StepStatus::Success, std::time::Duration::ZERO, None);
508→        state.record_step_result("b", StepStatus::Success, std::time::Duration::ZERO, None);
509→
510→        state.clear_all_steps();
511→
512→        assert!(state.steps.is_empty());
513→    }
514→}
