621→#[cfg(test)]
622→mod prune_tests {
623→    use super::*;
624→    use tempfile::TempDir;
625→
626→    #[test]
627→    fn prune_history_keeps_recent() {
628→        let temp = TempDir::new().unwrap();
629→        let project = super::super::ProjectId::from_path(temp.path()).unwrap();
630→        let mut state = StateStore::new(&project);
631→
632→        // Add 10 runs
633→        for i in 0..10 {
634→            let record = super::super::RunRecord {
635→                timestamp: Utc::now(),
636→                workflow: format!("run{}", i),
637→                duration_ms: 1000,
638→                status: super::super::RunStatus::Success,
639→                steps_run: vec![],
640→                steps_skipped: vec![],
641→                error: None,
642→            };
643→            state.record_run(record);
644→        }
645→
646→        assert_eq!(state.runs.len(), 10);
647→
648→        state.prune_history(5);
649→
650→        assert_eq!(state.runs.len(), 5);
651→        // Most recent should still be there
652→        assert_eq!(state.runs[0].workflow, "run9");
653→    }
654→
655→    #[test]
656→    fn prune_history_no_op_when_under_limit() {
657→        let temp = TempDir::new().unwrap();
