659→        let mut state = StateStore::new(&project);
660→
661→        // Add 3 runs
662→        for i in 0..3 {
663→            let record = super::super::RunRecord {
664→                timestamp: Utc::now(),
665→                workflow: format!("run{}", i),
666→                duration_ms: 1000,
667→                status: super::super::RunStatus::Success,
668→                steps_run: vec![],
669→                steps_skipped: vec![],
670→                error: None,
671→            };
672→            state.record_run(record);
673→        }
674→
675→        state.prune_history(5);
676→
677→        assert_eq!(state.runs.len(), 3);
678→    }
