  5→/// Information about the current shell environment.
  6→#[derive(Debug, Clone)]
  7→pub struct ShellInfo {
  8→    /// Shell executable path.
  9→    pub executable: PathBuf,
 10→
 11→    /// Shell name (bash, zsh, fish, powershell, cmd).
 12→    pub name: ShellType,
 13→
 14→    /// Config files that affect this shell.
 15→    pub config_files: Vec<PathBuf>,
 16→
 17→    /// Command to reload the shell.
 18→    pub reload_command: String,
 19→}
 20→
 21→/// Known shell types.
 22→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
 23→pub enum ShellType {
 24→    Bash,
 25→    Zsh,
 26→    Fish,
 27→    PowerShell,
 28→    Cmd,
 29→    Unknown,
 30→}
 31→
 32→impl ShellType {
 33→    /// Parse shell type from executable name.
 34→    pub fn from_executable(exe: &str) -> Self {
 35→        let name = std::path::Path::new(exe)
 36→            .file_stem()
 37→            .and_then(|s| s.to_str())
 38→            .unwrap_or("")
 39→            .to_lowercase();
 40→
 41→        match name.as_str() {
 42→            "bash" => ShellType::Bash,
 43→            "zsh" => ShellType::Zsh,
 44→            "fish" => ShellType::Fish,
 45→            "powershell" | "pwsh" => ShellType::PowerShell,
 46→            "cmd" => ShellType::Cmd,
 47→            _ => ShellType::Unknown,
 48→        }
 49→    }
 50→}
 51→
 52→/// Detect the current shell environment.
 53→pub fn detect_shell() -> ShellInfo {
 54→    let executable = get_shell_executable();
 55→    let shell_type = ShellType::from_executable(&executable.to_string_lossy());
 56→
 57→    ShellInfo {
 58→        executable: executable.clone(),
 59→        name: shell_type,
 60→        config_files: get_config_files(shell_type),
 61→        reload_command: get_reload_command(shell_type, &executable),
 62→    }
 63→}
 64→
 65→fn get_shell_executable() -> PathBuf {
 66→    if cfg!(target_os = "windows") {
