  1→//! Environment change detection.
  2→
  3→use std::collections::HashSet;
  4→use std::path::PathBuf;
  5→
  6→/// Detected environment change.
  7→#[derive(Debug, Clone)]
  8→pub struct EnvironmentChange {
  9→    pub kind: EnvironmentChangeKind,
 10→    pub message: String,
 11→    pub action_required: bool,
 12→}
 13→
 14→/// Type of environment change.
 15→#[derive(Debug, Clone, PartialEq)]
 16→pub enum EnvironmentChangeKind {
 17→    /// PATH was modified.
 18→    PathChanged {
 19→        added: Vec<String>,
 20→        removed: Vec<String>,
 21→    },
 22→    /// Shell config file was modified.
 23→    ShellConfigModified(String),
 24→    /// New tool requires shell restart.
 25→    ShellRestartRequired,
 26→}
 27→
 28→/// Detects changes to the shell environment.
 29→pub struct EnvironmentDetector {
 30→    initial_path: String,
 31→    shell_config_files: Vec<PathBuf>,
 32→}
 33→
 34→impl EnvironmentDetector {
 35→    /// Create a new environment detector capturing current state.
 36→    pub fn new() -> Self {
 37→        let shell_config_files = Self::get_shell_config_files();
 38→
 39→        Self {
 40→            initial_path: std::env::var("PATH").unwrap_or_default(),
 41→            shell_config_files,
 42→        }
 43→    }
 44→
 45→    /// Check for environment changes.
 46→    pub fn check_changes(&self) -> Vec<EnvironmentChange> {
 47→        let mut changes = Vec::new();
 48→
 49→        let current_path = std::env::var("PATH").unwrap_or_default();
 50→        if current_path != self.initial_path {
 51→            let initial: HashSet<_> = self.initial_path.split(':').collect();
 52→            let current: HashSet<_> = current_path.split(':').collect();
 53→
 54→            let added: Vec<_> = current
 55→                .difference(&initial)
 56→                .map(|s| s.to_string())
 57→                .collect();
 58→            let removed: Vec<_> = initial
 59→                .difference(&current)
 60→                .map(|s| s.to_string())
 61→                .collect();
 62→
 63→            if !added.is_empty() || !removed.is_empty() {
 64→                changes.push(EnvironmentChange {
 65→                    kind: EnvironmentChangeKind::PathChanged {
 66→                        added: added.clone(),
 67→                        removed: removed.clone(),
 68→                    },
 69→                    message: format!(
 70→                        "PATH modified: {} added, {} removed",
 71→                        added.len(),
 72→                        removed.len()
 73→                    ),
 74→                    action_required: !added.is_empty(),
 75→                });
 76→            }
 77→        }
 78→
 79→        changes
 80→    }
 81→
 82→    /// Get the appropriate shell reload command.
 83→    pub fn get_shell_reload_command() -> Option<String> {
 84→        let shell = std::env::var("SHELL").ok()?;
 85→
 86→        if shell.contains("zsh") || shell.contains("bash") {
 87→            Some("exec $SHELL".to_string())
 88→        } else if shell.contains("fish") {
 89→            Some("exec fish".to_string())
 90→        } else {
 91→            None
 92→        }
 93→    }
 94→
 95→    /// Get common shell config file paths.
 96→    fn get_shell_config_files() -> Vec<PathBuf> {
 97→        let home = dirs::home_dir().unwrap_or_else(|| PathBuf::from("~"));
 98→
 99→        vec![
100→            home.join(".zshrc"),
101→            home.join(".bashrc"),
102→            home.join(".bash_profile"),
103→            home.join(".profile"),
104→            home.join(".config/fish/config.fish"),
105→        ]
106→        .into_iter()
107→        .filter(|p| p.exists())
108→        .collect()
109→    }
110→
111→    /// Check if shell restart is needed after a step.
112→    pub fn needs_shell_restart(step_template: &str) -> bool {
113→        matches!(
114→            step_template,
115→            "mise" | "asdf" | "volta" | "nvm" | "rbenv" | "pyenv" | "brew"
116→        )
117→    }
118→
119→    /// Get the initial PATH.
120→    pub fn initial_path(&self) -> &str {
121→        &self.initial_path
122→    }
123→
124→    /// Get the list of shell config files.
125→    pub fn shell_config_files(&self) -> &[PathBuf] {
126→        &self.shell_config_files
127→    }
128→}
129→
130→impl Default for EnvironmentDetector {
131→    fn default() -> Self {
132→        Self::new()
133→    }
134→}
